$('arrivalFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;const lines=(await file.text()).trim().split(/\r?\n/),headers=lines.shift().split(',').map(s=>s.trim());let accepted=0,rejected=0;const imported=new Map(),seen=new Set();for(const line of lines){const cells=line.split(',').map(s=>s.trim()),r=Object.fromEntries(headers.map((h,i)=>[h,cells[i]])),sched=D.observations.timetables[r.trip_id],stop=D.route.stops.find(s=>s.stop_id===r.stop_id),time=Date.parse(r.observed_arrival);if(!sched||!stop||!Number.isFinite(time)||!/(Z|[+-]\d\d:\d\d)$/.test(r.observed_arrival)||new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Lisbon'}).format(new Date(time))!==D.route.study_date||seen.has(r.trip_id+'|'+r.stop_id)){rejected++;continue}seen.add(r.trip_id+'|'+r.stop_id);const late=(time-Date.parse(D.study_midnight))/1000-sched.stops[r.stop_id];if(!imported.has(r.trip_id))imported.set(r.trip_id,{trip_id:'upload:'+r.trip_id,passages:[],samples:0});imported.get(r.trip_id).passages.push({stop_id:r.stop_id,lateness_low:late,lateness_high:late,from:new Date(time).toISOString(),to:new Date(time).toISOString(),kind:'user-supplied arrival, not independently verified'});accepted++}const incomingIds=new Set([...imported.values()].map(t=>t.trip_id));D.observations.trips=D.observations.trips.filter(t=>!incomingIds.has(t.trip_id));D.observations.trips.push(...imported.values());if(imported.size)observedTrip=[...imported.values()][0].trip_id;drawObserved();$('importStatus').textContent=`${tr('uploadDone')}: ${accepted}; ${tr('uploadRejected')}: ${rejected}`};
function tick(now){const dt=lastFrame?Math.min(.15,(now-lastFrame)/1000):0;lastFrame=now;if(state.playing){state.time=Math.min(2400,state.time+dt*state.speed);replayDraw();if(state.time>=2400){state.playing=false;if(recorder?.state==='recording')recorder.stop()}}requestAnimationFrame(tick)}window.addEventListener('resize',replayDraw);if(state.variant==='custom'&&!D.cases[state.case]?.custom)state.variant='restricted';if(state.variant.startsWith('leg_'))state.case='busy';draft=state.variant==='draft'?(q.get('priority')||'').split(',').filter(id=>D.route.segments.some(s=>s.id===id)):[...mask(state.variant)];render();requestAnimationFrame(tick);
